return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'es_ES','project-id-version'=>'Quevedo','pot-creation-date'=>'2025-05-05 13:24+0200','po-revision-date'=>'2025-05-05 13:25+0200','x-generator'=>'Poedit 3.6','messages'=>['Quevedo writer tools'=>'Quevedo - Herramientas para escritores','WordPress was born as a small blogging tool. Over the years it has grown and now serves for many more things, but deep down there is still a lot of that little blogging tool.'=>'WordPress nació siendo una pequeña herramienta para blogs. Con los años ha crecido y ahora sirve para muchas cosas más, pero en el fondo todavía queda mucho de esa pequeña herramienta para hacer blogs.','Quevedo is a set of tools aimed at those authors, writers or bloggers who want to use WordPress for writing. It removes some unnecessary features for single-author sites and improves SEO, but without complications.'=>'Quevedo is a set of tools aimed at those authors, writers or bloggers who want to use WordPress for writing. It removes some unnecessary features for single-author sites and improves SEO, but without complications.','WordPress features'=>'Características de WordPress','Some minor theaks to make WordPress a bit more appealing to bloggers and single-user site owners.'=>'Algunos retoques menores para hacer que WordPress sea un poco más atractivo para los bloggers y los propietarios de sitios de un solo autor.','Featured image'=>'Imagen destacada','Options for featured images on your posts.'=>'Opciones de imagen destacada para tus entradas.','Default featured image'=>'Imagen destacada por defecto','Select a fallback image for posts that do not have a featured image set.'=>'Selecciona una imagen de respaldo para las entradas que no tengan imagen destacada.','Select default image'=>'Seleccionar imagen por defecto','Use this image'=>'Usar esta imagen','Select image'=>'Seleccionar imagen','Remove image'=>'Quitar imagen','Featured image options'=>'Opciones de imagen destacada','Shortcodes'=>'Shortcodes','Returns the current year in four-digit format. Very useful for copyright notices.'=>'Devuelve el año actual en formato de cuatro dígitos. Muy útil para los avisos de copyright.','Returns a paragraph full of "Lorem ipsum" fill text. The optional attribute "words" defines the number of words, default is 200.'=>'Devuelve un párrafo con texto de relleno "Lorem ipsum". El atributo opcional "words" define el número de palabras, por defecto es 200.','Options saved!'=>'¡Opciones guardadas!','Error saving configuration to database.'=>'Error al guardar la configuración a base de datos.','No changes were needed.'=>'No había nada que guardar.','Disable post tags'=>'Desactivar las etiquetas de entradas','If not used properly, post tags can create a lot of duplicate content in your site.'=>'Si no se utilizan correctamente, las etiquetas de las entradas pueden crear mucho contenido duplicado en tu sitio.','Disable post formats'=>'Desactivar los formatos de entrada','If you are not using posts formats they only add clutter to the post editor'=>'Si no utilizas los formatos de entrada, sólo añaden desorden al editor de entradas','Disable author archives'=>'Desactivar los archivos de autor','If you have a single-user blog, the author archive will be exactly the same as your homepage. This could lead to duplicate content SEO issues.'=>'Si tienes un blog con un solo autor, el archivo de autor será exactamente igual que tu página de inicio. Esto podría dar lugar a problemas de SEO de contenido duplicado.','Disable date archives'=>'Desactivar los archivos por fecha','Date archive pages (year, month and day) can create duplicate or thin content on personal blogs. This feature redirects them to your homepage.'=>'Las páginas de archivo por fecha (año, mes y día) pueden crear contenido duplicado o superficial en blogs personales. Esta función las redirige a tu página de inicio.','Redirect attachment pages to parent post'=>'Redirigir páginas de adjuntos a su entrada','WordPress creates a simgle pagle for each gallery image, creating a lot of thin content. This feature redirects the attachment page to the post the image is attached to.'=>'WordPress crea una página individual para cada imagen de la galería, creando un montón de contenido instancial. Esta función redirige la página de adjuntos a la entrada a la que se adjunta la imagen.','Simplify editor blocks'=>'Simplificar los bloques del editor','When editing a blog post, the available blocks are reduced to: paragraph, heading, list, image, quote, separator, code, preformatted.'=>'Al editar una entrada del blog, los bloques disponibles se reducen a: párrafo, encabezado, lista, imagen, cita, separador, código, preformateado.','Add featured image to post metadata'=>'Añadir imagen destacada a los metadatos de la entrada','Outputs Open Graph and Twitter image meta tags with the post featured image, or with the default featured image if the post has none.'=>'Añade los metadatos de imagen de Open Graph y Twitter con la imagen destacada de la entrada o, si no tiene, con la imagen destacada por defecto.','Quevedo'=>'Quevedo','Settings'=>'Ajustes','Nilo Velez'=>'Nilo Velez','https://www.nilovelez.com'=>'https://www.nilovelez.com']];